/*
 * [Usage]
 *
 * var l = require('logger.js');
 * var logger = l.createLogger('SSIP', 'Release');
 */

function Logger(tag, mode) {
    this.tag = (tag + '     ').substr(0, 5);

    if (mode != Logger.MODE_RELEASE && mode != Logger.MODE_DEBUG) {
        this.mode = Logger.MODE_RELEASE;
    } else {
        this.mode = mode;
    }
};

// log mode
Logger.MODE_RELEASE = 'Release';
Logger.MODE_DEBUG   = 'Debug';

// log level
Logger.VERBOSE = 5; // V
Logger.DETAIL  = 4; // D
Logger.INFO    = 3; // I
Logger.WARN    = 2; // W
Logger.ERROR   = 1; // E

Logger.prototype._log = function(level, message) {
    var msg = '          [';
    switch (level) {
    case Logger.VERBOSE:
        msg += 'V';
        break;
    case Logger.DETAIL:
        msg += 'D';
        break;
    case Logger.INFO:
        msg += 'I';
        break;
    case Logger.WARN:
        msg += 'W';
        break;
    case Logger.ERROR:
        msg += 'E';
        break;
    default:
        msg += ' ';
        break;
    }
    msg += ' ';
    msg += this.tag;
    msg += '] ';
    msg += message;
    console.log(msg);
};

Logger.prototype.dlog = function(level, message) {
    if (this.mode == Logger.MODE_DEBUG) {
        this._log(level, message);
    }
};

Logger.prototype.rlog = function(level, message) {
    this._log(level, message);
};

exports.Logger = Logger;

exports.createLogger = function(tag, mode) {
    return new Logger(tag, mode);
};
